{
 "kind": "sequence",
 "format": 1,
 "id": "seq_deadball_break_blowout",
 "name": "Deadball: the stretch, a blowout",
 "set": "set_ksab5_desk",
 "roles": {
  "a": {
   "mark": "a",
   "label": "Lead anchor"
  },
  "b": {
   "mark": "b",
   "label": "Analyst"
  }
 },
 "wallText": "{status}",
 "wallSub": "KSAB5 Sports",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "drift",
    "cut": "dissolve"
   },
   "say": {
    "role": "a",
    "lines": [
     "{leader} lead by {margin}, and the stretch is about all that's left. {away} {awayScore}, {home} {homeScore}."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    }
   ],
   "wall": "feed"
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "b"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "{trailer} are done. Rest the arms and get on the bus.",
     "I'd start thinking about tomorrow if I'm {trailer}."
    ]
   },
   "gfx": [
    {
     "kind": "table",
     "title": "The scoring",
     "list": "scoring",
     "row": "{inning}: {away} to {home}",
     "limit": 6,
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "a",
     "b"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "Back to {announcer} for the {nextOrd}."
    ]
   },
   "gfx": [],
   "wall": "feed"
  }
 ]
}
